// spec: specs/pwa-install-prompt.md (1.1, 1.2) · кейсы: .qa/tests/pwa-install-prompt/PWA-01.md, PWA-02.md
// 1.1 — seed: tests/seed.admin.spec.ts (admin, ../auth/admin.json; файл не перезаписывается) — с #359741 /guides видит только админ.
//   Ограничение: вошедшему окно само не показывается нигде (#81a046, PWA-04), поэтому тест подтверждает только
//   «поверх играющего видео на /guides окна нет»; гостевую логику таймера на /guides проверить нельзя, пока гайды скрыты.
// 1.2 — seed: tests/seed.spec.ts (гость, чистый localStorage) — контроль, что окно в этом окружении вообще работает.
// Проект iphone (WebKit, iPhone 13 Mini 375) · прод, только просмотр. Тикет #631293 («מה רצוי»: «החלון לא יקפוץ מעל סרטון שמתנגן בעמוד /guides»).
// 15 с ожидания из ручной проверки заменены page.clock.runFor: таймер окна (3000 мс) проматывается, видео играет в реальном времени.
import { test, expect } from '@playwright/test';
import { GUIDES, openGuides, videoOf, videoState, expectPlaying } from '../guides-videos/guides.helpers';
import {
  prepareReadOnly, rpcResponse, installDialog, laterButton, chooseEssentialCookies, LOAD,
} from './pwa.helpers';

test.describe('Окно установки PWA — /guides (admin) и контроль на главной (гость) (#631293)', () => {
  test.describe('admin', () => {
    // Продление сессии (/auth/v1/) не разрешается (keepAuth=false) — общий файл сессии admin не меняется.
    test.use({ storageState: '../auth/admin.json' });

    test('/guides (admin): окно «אל תחמיצו אף הזדמנות» не всплывает поверх играющего видео (≥ 30 с по часам страницы) #631293 #359741 @iphone @prod-safe', async ({ page, context }) => {
      await prepareReadOnly(context);
      await page.addLocatorHandler(page.getByRole('button', { name: 'חיוניים בלבד' }), (b) => b.click());
      await page.clock.install();
      await openGuides(page);

      const g = GUIDES.find((x) => x.id === 'publish')!;
      const video = videoOf(page, g);
      await video.tap(); // сам прокручивает и переискивает плеер после перерисовки админской страницы
      await expectPlaying(video, 0.5, g.id);

      // Между промотками — реальное воспроизведение (видео идёт дальше): даёт странице отрисовать окно, если бы оно сработало.
      await page.clock.runFor(15_000);
      let t = (await videoState(video)).currentTime;
      await expectPlaying(video, t + 1, g.id);
      await page.clock.runFor(15_000);
      t = (await videoState(video)).currentTime;
      await expectPlaying(video, t + 1, g.id);

      await expect(installDialog(page), 'окно установки не показано на /guides').toBeHidden();
      await expect(laterButton(page), 'кнопки окна нет').toHaveCount(0);
      await expect(page, 'остались на /guides').toHaveURL(/\/guides\/?$/);
      const s = await videoState(video);
      expect(s.paused, 'видео продолжает играть').toBe(false);
      expect(s.error, 'video.error').toBeNull();
    });
  });

  test('контроль: на главной (/) окно «אל תחמיצו אף הזדמנות» появляется после выбора cookie (~3 с), закрывается «אולי מאוחר יותר» #631293 #81a046 @iphone @prod-safe', async ({ page, context }) => {
    await prepareReadOnly(context);
    await page.clock.install();
    const rpc = rpcResponse(page);
    await page.goto('/');
    await chooseEssentialCookies(page);
    expect((await rpc).status(), 'RPC pwa_app_last_opened ответил').toBe(200);

    await page.clock.runFor(4_000); // таймер окна — 3000 мс (принято вручную: 3,9–4,8 с после «חיוניים בלבד»)
    await expect(installDialog(page), 'окно установки появилось на главной').toBeVisible(LOAD);
    await expect(page.getByRole('button', { name: 'הוספה עכשיו' }), 'кнопка «הוספה עכשיו»').toBeVisible();
    await expect(laterButton(page), 'кнопка «אולי מאוחר יותר»').toBeVisible();

    await laterButton(page).click();
    await expect(installDialog(page), 'окно закрыто').toBeHidden();
  });
});
